function ProjectsPage() {
  const [, setLocation] = useLocation();
  const projectsQuery = trpc.dashboard.projects.useQuery(undefined, { retry: false });
  const create = trpc.projects.create.useMutation({ onSuccess: () => { projectsQuery.refetch(); toast.success("Project draft created"); }, onError: (error) => toast.error(error.message) });
  const approve = trpc.projects.approve.useMutation({ onSuccess: () => { projectsQuery.refetch(); toast.success("Project approved"); }, onError: (error) => toast.error(error.message) });
  const activate = trpc.projects.activate.useMutation({ onSuccess: (ok) => { projectsQuery.refetch(); toast(ok ? "Project activated" : "Project is not ready to activate", { description: ok ? "Any previous active project was deactivated." : "Complete training and approve the project first." }); }, onError: (error) => toast.error(error.message) });
  const rows = projectsQuery.data ?? [];
  const createProject = () => { const name = window.prompt("Project name"); if (!name?.trim()) return; const projectKey = name.trim().toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, "").slice(0, 80); create.mutate({ projectKey: `${projectKey}-${Date.now()}`, name: name.trim(), snapshot: JSON.stringify({ name: name.trim(), status: "draft" }) }); };
  const statusLabel = (status: string) => status === "active" ? "Active" : status === "approved" || status === "ready" ? "Ready to activate" : status === "training" ? "Training" : status[0].toUpperCase() + status.slice(1);
  return <div className="mx-auto max-w-[1440px] px-4 pb-12 pt-6 sm:px-6 lg:px-8 lg:pt-9"><PageHeader eyebrow="Workspace / Projects" title="Projects" description="Create, train, approve, and activate the service package WEBASI uses to guide clients." action={<button onClick={createProject} disabled={create.isPending} className="webasi-button-primary"><Plus className="h-4 w-4" />New project</button>} /><div className="mb-5 grid gap-4 sm:grid-cols-3"><MetricCard label="Total projects" value={String(rows.length)} detail={`${rows.filter((project) => project.status === "active").length} active`} icon={FolderKanban} /><MetricCard label="Knowledge readiness" value={rows.length ? `${Math.round(rows.reduce((sum, project) => sum + project.readiness, 0) / rows.length)}%` : "0%"} detail="Across all projects" icon={Sparkles} tone="violet" /><MetricCard label="Ready to activate" value={String(rows.filter((project) => project.status === "approved" || project.status === "ready").length)} detail="Approved project versions" icon={CheckCircle2} tone="green" /></div><section className="webasi-card overflow-hidden"><div className="flex items-center justify-between border-b border-[#E2E8F0] p-5"><div><h2 className="text-base font-bold text-[#0F172A]">Your service packages</h2><p className="mt-1 text-xs text-[#94A3B8]">Only one project can be active at a time. Activation requires an approved, ready project.</p></div><button onClick={() => projectsQuery.refetch()} disabled={projectsQuery.isFetching} className="webasi-button-secondary min-h-9 px-3"><RefreshCw className={cn("h-3.5 w-3.5", projectsQuery.isFetching && "animate-spin")} />Refresh</button></div><div className="divide-y divide-[#F1F5F9]">{projectsQuery.isLoading ? <div className="p-6 text-xs text-[#94A3B8]">Loading persisted projects…</div> : rows.length === 0 ? <div className="p-6 text-xs text-[#94A3B8]">No projects yet. Create a draft to begin training.</div> : rows.map((project) => <div key={project.projectKey} className="flex flex-col gap-4 p-5 sm:flex-row sm:items-center sm:justify-between"><div className="flex items-start gap-3"><div className={cn("mt-0.5 flex h-10 w-10 shrink-0 items-center justify-center rounded-xl", project.status === "active" ? "bg-[#EFF6FF] text-[#2563FF]" : "bg-[#F8FAFC] text-[#64748B]")}><FolderKanban className="h-4 w-4" /></div><div><div className="flex flex-wrap items-center gap-2"><p className="text-sm font-semibold text-[#1E293B]">{project.name}</p><span className={cn("rounded-full px-2 py-0.5 text-[10px] font-bold", project.status === "active" ? "bg-[#DCFCE7] text-[#15803D]" : project.status === "approved" || project.status === "ready" ? "bg-[#EFF6FF] text-[#1D4ED8]" : "bg-[#F1F5F9] text-[#64748B]")}>{statusLabel(project.status)}</span></div><p className="mt-1 text-xs text-[#94A3B8]">Version {project.version} · Updated {new Date(project.updatedAt).toLocaleString([], { dateStyle: "medium", timeStyle: "short" })}</p></div></div><div className="flex items-center gap-4"><div className="hidden text-right sm:block"><p className="text-xs font-bold text-[#1E293B]">{project.readiness}%</p><p className="text-[10px] text-[#94A3B8]">knowledge ready</p></div>{project.status === "active" ? <span className="inline-flex items-center gap-1.5 rounded-full bg-[#DCFCE7] px-2.5 py-1.5 text-[10px] font-bold text-[#15803D]"><CheckCircle2 className="h-3.5 w-3.5" />Active</span> : project.status === "approved" || project.status === "ready" ? <button onClick={() => activate.mutate({ projectKey: project.projectKey })} disabled={activate.isPending} className="webasi-button-primary min-h-9 px-3">Activate</button> : <><button onClick={() => setLocation("/training")} className="webasi-button-secondary min-h-9 px-3">Continue training</button>{project.readiness >= 100 && <button onClick={() => approve.mutate({ projectKey: project.projectKey })} disabled={approve.isPending} className="webasi-button-primary min-h-9 px-3">Approve</button>}</>}<button className="flex h-8 w-8 items-center justify-center rounded-lg text-[#94A3B8] hover:bg-[#F8FAFC]" aria-label="Project options"><MoreHorizontal className="h-4 w-4" /></button></div></div>)}</div></section></div>;
}

function parseConversationMessages(raw: string) {
  try { return JSON.parse(raw) as Array<{ role: string; text: string }>; } catch { return []; }
}

function ConversationsPage() {
  const conversationsQuery = trpc.dashboard.conversations.useQuery(undefined, { refetchInterval: 10000, retry: false });
  const [selectedClientId, setSelectedClientId] = useState<string | null>(null);
  const [search, setSearch] = useState("");
  const resume = trpc.conversations.resume.useMutation({ onSuccess: () => { conversationsQuery.refetch(); toast.success("WEBASI resumed for this chat"); }, onError: (error) => toast.error(error.message) });
  const rows = conversationsQuery.data ?? [];
  const filtered = rows.filter((row) => !search.trim() || (row.profileName ?? row.waId).toLowerCase().includes(search.toLowerCase()) || row.state.toLowerCase().includes(search.toLowerCase()));
  const selected = filtered.find((row) => row.clientId === selectedClientId) ?? filtered[0] ?? null;
  useEffect(() => { if (selected && selected.clientId !== selectedClientId) setSelectedClientId(selected.clientId); }, [selected?.clientId, selectedClientId]);
  const messages = selected ? parseConversationMessages(selected.recentMessages) : [];
  const initials = (selected?.profileName ?? selected?.waId ?? "?").split(/\\s+/).map((part) => part[0]).slice(0, 2).join("").toUpperCase();
  const lastActivity = selected?.updatedAt ? new Date(selected.updatedAt).toLocaleString([], { dateStyle: "medium", timeStyle: "short" }) : "No activity yet";
  const resumeSelected = () => { if (!selected || !selected.isPaused) return; if (window.confirm("Resume WEBASI automation for this chat?")) resume.mutate({ clientId: selected.clientId }); };
  return <div className="mx-auto max-w-[1440px] px-4 pb-12 pt-6 sm:px-6 lg:px-8 lg:pt-9">
    <PageHeader eyebrow="Workspace / Inbox" title="Conversations" description="Review live WhatsApp chats, see owner takeover state, and resume automation when you are ready." action={<button onClick={() => conversationsQuery.refetch()} className="webasi-button-secondary" disabled={conversationsQuery.isFetching}><RefreshCw className={cn("h-4 w-4", conversationsQuery.isFetching && "animate-spin")} />Refresh</button>} />
    <div className="grid gap-5 lg:grid-cols-[320px_minmax(0,1fr)]">
      <section className="webasi-card overflow-hidden"><div className="border-b border-[#E2E8F0] p-4"><div className="relative"><Search className="absolute left-3 top-2.5 h-4 w-4 text-[#94A3B8]" /><input value={search} onChange={(event) => setSearch(event.target.value)} className="h-9 w-full rounded-lg border border-[#E2E8F0] bg-[#F8FAFC] pl-9 pr-3 text-xs outline-none focus:border-[#2563FF]" placeholder="Search conversations" /></div><div className="mt-3 flex gap-1.5"><span className="rounded-full bg-[#EFF6FF] px-2.5 py-1 text-[10px] font-bold text-[#1D4ED8]">All {rows.length}</span><span className="rounded-full bg-[#FFF7ED] px-2.5 py-1 text-[10px] font-semibold text-[#C2410C]">Paused {rows.filter((row) => row.isPaused).length}</span></div></div><div className="divide-y divide-[#F1F5F9]">{conversationsQuery.isLoading ? <div className="p-5 text-xs text-[#94A3B8]">Loading live conversations…</div> : filtered.length === 0 ? <div className="p-5 text-xs text-[#94A3B8]">No live conversations match this search.</div> : filtered.map((item) => { const itemInitials = (item.profileName ?? item.waId).split(/\\s+/).map((part) => part[0]).slice(0, 2).join("").toUpperCase(); return <button key={item.clientId} onClick={() => setSelectedClientId(item.clientId)} className={cn("flex w-full items-start gap-3 p-4 text-left transition", selected?.clientId === item.clientId ? "bg-[#EFF6FF]" : "hover:bg-[#FAFCFF]")}><div className={cn("flex h-9 w-9 shrink-0 items-center justify-center rounded-full text-[11px] font-bold", item.isPaused ? "bg-[#FFF7ED] text-[#C2410C]" : "bg-[#DBEAFE] text-[#1D4ED8]")}>{itemInitials}</div><div className="min-w-0 flex-1"><div className="flex items-center justify-between gap-2"><p className="truncate text-xs font-semibold text-[#1E293B]">{item.profileName ?? item.waId}</p><span className="shrink-0 text-[10px] text-[#94A3B8]">{new Date(item.updatedAt).toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" })}</span></div><p className="mt-1 truncate text-[11px] text-[#64748B]">{parseConversationMessages(item.recentMessages).at(-1)?.text ?? "No message content"}</p><span className={cn("mt-2 inline-flex rounded-full px-2 py-0.5 text-[10px] font-medium", item.isPaused ? "bg-[#FFF7ED] text-[#C2410C]" : "bg-[#F1F5F9] text-[#64748B]")}>{item.isPaused ? "Paused by owner" : item.state.replaceAll("_", " ")}</span></div></button>; })}</div></section>
      <section className="webasi-card flex min-h-[600px] flex-col overflow-hidden">{selected ? <><div className="flex flex-col gap-3 border-b border-[#E2E8F0] p-4 sm:flex-row sm:items-center sm:justify-between"><div className="flex items-center gap-3"><div className={cn("flex h-10 w-10 items-center justify-center rounded-full text-xs font-bold", selected.isPaused ? "bg-[#FFF7ED] text-[#C2410C]" : "bg-[#DBEAFE] text-[#1D4ED8]")}>{initials}</div><div><p className="text-sm font-bold text-[#1E293B]">{selected.profileName ?? selected.waId}</p><p className="mt-0.5 flex items-center gap-1.5 text-[11px] text-[#64748B]"><StatusDot color={selected.isPaused ? "#F59E0B" : "#22C55E"} />{selected.isPaused ? "Paused by owner" : "WEBASI active"} · {selected.state.replaceAll("_", " ")}</p></div></div><div className="flex items-center gap-2">{selected.isPaused ? <button onClick={resumeSelected} disabled={resume.isPending} className="webasi-button-primary min-h-9 px-3"><Play className="h-3.5 w-3.5" />{resume.isPending ? "Resuming…" : "Resume automation"}</button> : <span className="inline-flex items-center gap-1.5 rounded-full bg-[#F0FDF4] px-2.5 py-1.5 text-[10px] font-bold text-[#15803D]"><CheckCircle2 className="h-3.5 w-3.5" />Automation active</span>}<button onClick={() => toast("Takeover mode is controlled from the linked owner WhatsApp device.")} className="webasi-button-secondary min-h-9 px-3"><MessageCircle className="h-3.5 w-3.5" />Take over</button></div></div><div className="flex-1 space-y-4 overflow-auto bg-[#F8FAFC] p-4 sm:p-6">{messages.length === 0 ? <div className="flex h-full items-center justify-center text-xs text-[#94A3B8]">No message history stored yet.</div> : messages.map((message, index) => <div key={"message-" + message.role + "-" + index + "-" + message.text} className={cn("flex", message.role === "assistant" ? "justify-start" : "justify-end")}><div className={cn("max-w-[82%] rounded-2xl px-4 py-3 text-sm leading-6 shadow-sm", message.role === "assistant" ? "rounded-bl-md border border-[#E2E8F0] bg-white text-[#1E293B]" : "rounded-br-md bg-[#2563FF] text-white")}>{message.text}<span className={cn("mt-1 block text-[10px]", message.role === "assistant" ? "text-[#94A3B8]" : "text-blue-100")}>{message.role === "assistant" ? "WEBASI" : "Client"}</span></div></div>)}<div className="flex items-center justify-center gap-2 text-[10px] text-[#94A3B8]"><span className="h-px w-10 bg-[#E2E8F0]" />Last activity {lastActivity}<span className="h-px w-10 bg-[#E2E8F0]" /></div></div><div className="border-t border-[#E2E8F0] bg-white p-4"><div className="flex items-center gap-2 rounded-xl border border-[#E2E8F0] bg-[#F8FAFC] p-2"><MessageSquareText className="ml-2 h-4 w-4 text-[#94A3B8]" /><span className="flex-1 px-2 text-xs text-[#64748B]">Owner replies from WhatsApp automatically pause this chat.</span></div></div></> : <div className="flex flex-1 items-center justify-center p-8 text-sm text-[#64748B]">No live WhatsApp conversations yet.</div>}</section>
    </div>
  </div>;
}

function OrdersPage() {
  const ordersQuery = trpc.dashboard.orders.useQuery(undefined, { refetchInterval: 10000, retry: false });
  const confirm = trpc.orders.confirm.useMutation({ onSuccess: () => { ordersQuery.refetch(); toast.success("Deposit marked as confirmed", { description: "The client order is now ready for fulfillment." }); }, onError: (error) => toast.error(error.message) });
  const rows = ordersQuery.data ?? [];
  const awaiting = rows.filter((order) => order.state === "awaiting_deposit");
  const slips = rows.filter((order) => order.state === "slip_received");
  const confirmed = rows.filter((order) => order.state === "confirmed_by_owner");
  const money = (value: number) => `LKR ${value.toLocaleString()}`;
  const label = (state: string) => state === "awaiting_deposit" ? "Awaiting deposit" : state === "slip_received" ? "Slip received" : state === "confirmed_by_owner" ? "Confirmed by owner" : state.replaceAll("_", " ");
  const confirmOrder = (orderKey: string) => { if (window.confirm("Confirm this deposit only after you have verified the bank transfer and slip?")) confirm.mutate({ orderKey }); };
  return <div className="mx-auto max-w-[1440px] px-4 pb-12 pt-6 sm:px-6 lg:px-8 lg:pt-9"><PageHeader eyebrow="Workspace / Orders" title="Orders" description="Track deposits and confirm payments only after you verify the bank transfer manually." action={<button onClick={() => ordersQuery.refetch()} disabled={ordersQuery.isFetching} className="webasi-button-secondary"><RefreshCw className={cn("h-4 w-4", ordersQuery.isFetching && "animate-spin")} />Refresh</button>} /><div className="mb-5 grid gap-4 sm:grid-cols-3"><MetricCard label="Awaiting deposit" value={String(awaiting.length)} detail={`${money(awaiting.reduce((sum, order) => sum + order.depositAmount, 0))} total`} icon={Clock3} tone="amber" /><MetricCard label="Slips to verify" value={String(slips.length)} detail="Needs your review" icon={WalletCards} /><MetricCard label="Confirmed this month" value={String(confirmed.length)} detail={money(confirmed.reduce((sum, order) => sum + order.depositAmount, 0))} icon={CheckCircle2} tone="green" /></div><section className="webasi-card overflow-hidden"><div className="flex flex-col gap-3 border-b border-[#E2E8F0] p-5 sm:flex-row sm:items-center sm:justify-between"><div><h2 className="text-base font-bold text-[#0F172A]">Order pipeline</h2><p className="mt-1 text-xs text-[#94A3B8]">Every order is tied to a live WhatsApp conversation and active project.</p></div><span className="rounded-full bg-[#EFF6FF] px-2.5 py-1 text-[10px] font-bold text-[#1D4ED8]">All {rows.length}</span></div><div className="hidden grid-cols-[110px_1.3fr_1.3fr_130px_145px_160px] gap-4 border-b border-[#F1F5F9] bg-[#F8FAFC] px-5 py-3 text-[10px] font-bold uppercase tracking-[0.1em] text-[#94A3B8] md:grid"><span>Order</span><span>Client</span><span>Package</span><span>Deposit</span><span>Status</span><span>Created</span></div><div className="divide-y divide-[#F1F5F9]">{ordersQuery.isLoading ? <div className="p-6 text-xs text-[#94A3B8]">Loading persisted orders…</div> : rows.length === 0 ? <div className="p-6 text-xs text-[#94A3B8]">No orders have been created yet.</div> : rows.map((order) => <div key={order.orderKey} className="grid gap-3 p-5 md:grid-cols-[110px_1.3fr_1.3fr_130px_145px_160px] md:items-center md:gap-4"><div><p className="text-xs font-bold text-[#1D4ED8]">{order.orderKey}</p><p className="mt-1 text-[10px] text-[#94A3B8] md:hidden">{new Date(order.createdAt).toLocaleString([], { dateStyle: "medium", timeStyle: "short" })}</p></div><div><p className="text-xs font-semibold text-[#1E293B]">{order.clientId}</p><p className="mt-1 text-[11px] text-[#94A3B8]">WhatsApp · {order.waId}</p></div><p className="text-xs text-[#64748B]">{order.packageName}</p><p className="text-sm font-bold text-[#1E293B]">{money(order.depositAmount)}</p><div><span className={cn("inline-flex rounded-full px-2.5 py-1 text-[10px] font-bold", order.state === "confirmed_by_owner" ? "bg-[#DCFCE7] text-[#15803D]" : order.state === "slip_received" ? "bg-[#FFF7ED] text-[#C2410C]" : "bg-[#EFF6FF] text-[#1D4ED8]")}>{label(order.state)}</span>{order.state === "slip_received" && <button onClick={() => confirmOrder(order.orderKey)} disabled={confirm.isPending} className="mt-2 block text-[10px] font-bold text-[#2563FF] hover:text-[#1D4ED8]">Verify &amp; confirm</button>}{order.notes && <p className="mt-1 text-[10px] text-[#94A3B8]">{order.notes}</p>}</div><p className="hidden text-[11px] text-[#64748B] md:block">{new Date(order.createdAt).toLocaleString([], { dateStyle: "medium", timeStyle: "short" })}</p></div>)}</div><div className="flex items-start gap-2 border-t border-[#E2E8F0] bg-[#FFFBEB] p-4 text-[11px] leading-5 text-[#92400E]"><AlertCircle className="mt-0.5 h-3.5 w-3.5 shrink-0" /><span>WEBASI never confirms payment automatically. Only your manual action above changes an order to Confirmed by owner.</span></div></section></div>;
}

function InsightsPage() {
  const insightsQuery = trpc.dashboard.insights.useQuery(undefined, { retry: false });
  const conversationsQuery = trpc.dashboard.conversations.useQuery(undefined, { retry: false });
  const analyze = trpc.insights.analyze.useMutation({ onSuccess: () => { insightsQuery.refetch(); conversationsQuery.refetch(); toast.success("Analysis complete", { description: "Suggestions were generated for review only." }); }, onError: (error) => toast.error(error.message) });
  const approve = trpc.insights.approve.useMutation({ onSuccess: () => { insightsQuery.refetch(); toast.success("Suggestion added to project draft"); }, onError: (error) => toast.error(error.message) });
  const rows = insightsQuery.data ?? [];
  const conversations = conversationsQuery.data ?? [];
  const messages = conversations.flatMap((row) => { try { return JSON.parse(row.recentMessages) as Array<{ role?: string; text?: string }>; } catch { return []; } });
  const questions = messages.filter((message) => (message.text ?? "").includes("?")).length;
  const escalations = conversations.filter((row) => row.state === "needs_owner").length;
  const singlish = messages.filter((message) => /\b(mata|one|puluwan|kiyada|hari|eka)\b/i.test(message.text ?? "")).length;
  const color = (category: string) => category === "Objection" ? "bg-[#FFF7ED] text-[#F59E0B]" : category === "Language" ? "bg-[#F5F3FF] text-[#7C3AED]" : "bg-[#EFF6FF] text-[#2563FF]";
  return <div className="mx-auto max-w-[1440px] px-4 pb-12 pt-6 sm:px-6 lg:px-8 lg:pt-9"><PageHeader eyebrow="Workspace / Insights" title="Insights" description="Spot recurring questions and drop-off patterns. Suggestions never change your knowledge automatically." action={<button onClick={() => analyze.mutate()} disabled={analyze.isPending} className="webasi-button-primary"><Sparkles className={cn("h-4 w-4", analyze.isPending && "animate-pulse")} />{analyze.isPending ? "Analyzing…" : "Run analysis"}</button>} /><div className="mb-5 grid gap-4 sm:grid-cols-3"><MetricCard label="Questions analyzed" value={String(questions)} detail={`Last ${conversations.length} conversations`} icon={MessageSquareText} /><MetricCard label="Escalations" value={String(escalations)} detail={conversations.length ? `${Math.round((escalations / conversations.length) * 100)}% of conversations` : "No live conversations"} icon={AlertCircle} tone="amber" /><MetricCard label="Language mix" value={`${Math.max(messages.length - singlish, 0)} / ${singlish}`} detail="English / Singlish markers" icon={TrendingUp} tone="violet" /></div><section className="webasi-card overflow-hidden"><div className="border-b border-[#E2E8F0] p-5"><div className="flex items-center gap-2"><div className="flex h-8 w-8 items-center justify-center rounded-lg bg-[#EFF6FF] text-[#2563FF]"><Sparkles className="h-4 w-4" /></div><div><h2 className="text-base font-bold text-[#0F172A]">Suggestions for your project</h2><p className="mt-1 text-xs text-[#94A3B8]">Generated from recent conversations. Review each suggestion before approval.</p></div></div></div><div className="divide-y divide-[#F1F5F9]">{insightsQuery.isLoading ? <div className="p-6 text-xs text-[#94A3B8]">Loading persisted insights…</div> : rows.length === 0 ? <div className="p-6 text-xs text-[#94A3B8]">No suggestions yet. Run analysis to inspect recent conversations.</div> : rows.map((insight) => <div key={insight.id} className="flex flex-col gap-4 p-5 sm:flex-row sm:items-center sm:justify-between"><div className="flex items-start gap-3"><div className={cn("mt-0.5 flex h-9 w-9 shrink-0 items-center justify-center rounded-lg", color(insight.category))}><MessageSquareText className="h-4 w-4" /></div><div><div className="flex flex-wrap items-center gap-2"><p className="text-sm font-semibold text-[#1E293B]">{insight.title}</p><span className={cn("rounded-full px-2 py-0.5 text-[10px] font-bold", color(insight.category))}>{insight.category}</span><span className={cn("rounded-full px-2 py-0.5 text-[10px] font-bold", insight.status === "approved" ? "bg-[#DCFCE7] text-[#15803D]" : "bg-[#F1F5F9] text-[#64748B]")}>{insight.status}</span></div><p className="mt-1.5 text-xs text-[#64748B]">{insight.detail}</p></div></div><button onClick={() => approve.mutate({ id: insight.id })} disabled={insight.status === "approved" || approve.isPending} className={cn("webasi-button min-h-9 shrink-0 px-3", insight.status === "approved" ? "border border-[#BBF7D0] bg-[#F0FDF4] text-[#15803D]" : "webasi-button-primary")}>{insight.status === "approved" ? <><Check className="h-3.5 w-3.5" />Approved</> : "Add to project"}</button></div>)}</div></section></div>;
}

function SettingsPage() {
  const settingsQuery = trpc.dashboard.settings.useQuery(undefined, { retry: false });
  const whatsappStatus = trpc.whatsapp.status.useQuery(undefined, { refetchInterval: 10000, retry: false });
  const update = trpc.settings.update.useMutation({ onSuccess: (ok) => { settingsQuery.refetch(); if (ok) toast.success("Settings saved"); else toast.error("WEBASI cannot turn on without an active approved project"); }, onError: (error) => toast.error(error.message) });
  const saved = settingsQuery.data;
  const [form, setForm] = useState({ businessName: "", bankDetails: "", notificationEmail: "", whatsappMonthlyCap: "900", geminiDailyCap: "500", webasiEnabled: false, shadowMode: false });
  useEffect(() => { if (saved) setForm({ businessName: saved.businessName, bankDetails: saved.bankDetails, notificationEmail: saved.notificationEmail ?? "", whatsappMonthlyCap: String(saved.whatsappMonthlyCap), geminiDailyCap: String(saved.geminiDailyCap), webasiEnabled: saved.webasiEnabled, shadowMode: saved.shadowMode }); }, [saved?.businessName, saved?.bankDetails, saved?.notificationEmail, saved?.whatsappMonthlyCap, saved?.geminiDailyCap, saved?.webasiEnabled, saved?.shadowMode]);
  const setField = (key: keyof typeof form, value: string | boolean) => setForm((current) => ({ ...current, [key]: value }));
  const submit = () => { if (form.webasiEnabled && !saved?.webasiEnabled && !window.confirm("Enable WEBASI live replies? This allows automated responses for the active project while WhatsApp is connected.")) return; update.mutate({ businessName: form.businessName.trim(), bankDetails: form.bankDetails.trim(), notificationEmail: form.notificationEmail.trim() || null, whatsappMonthlyCap: Number(form.whatsappMonthlyCap), geminiDailyCap: Number(form.geminiDailyCap), webasiEnabled: form.webasiEnabled, shadowMode: form.shadowMode }); };
  const input = (label: string, key: "businessName" | "notificationEmail" | "whatsappMonthlyCap" | "geminiDailyCap", helper?: string) => <label className="block"><span className="mb-2 block text-[11px] font-bold uppercase tracking-[0.08em] text-[#64748B]">{label}</span><input value={form[key]} onChange={(event) => setField(key, event.target.value)} type={key.includes("Cap") ? "number" : key === "notificationEmail" ? "email" : "text"} className="h-10 w-full rounded-lg border border-[#E2E8F0] bg-white px-3 text-xs font-medium text-[#1E293B] outline-none transition focus:border-[#2563FF] focus:ring-2 focus:ring-[#DBEAFE]" />{helper && <span className="mt-1.5 block text-[10px] text-[#94A3B8]">{helper}</span>}</label>;
  return <div className="mx-auto max-w-[1040px] px-4 pb-12 pt-6 sm:px-6 lg:px-8 lg:pt-9"><PageHeader eyebrow="Workspace / Settings" title="Settings" description="Control business details, notifications, usage caps, and the safety boundaries for WEBASI." action={<button onClick={submit} disabled={update.isPending || settingsQuery.isLoading} className="webasi-button-primary"><Check className="h-4 w-4" />{update.isPending ? "Saving…" : "Save changes"}</button>} /><div className="space-y-5"><SettingsSection title="Business profile" description="These details are stored in the project database and used for fixed replies and owner notifications."><div className="grid gap-4 sm:grid-cols-2">{input("Business name", "businessName")}{input("Notification email", "notificationEmail", "Used for escalations and payment-slip alerts.")}<div className="block"><span className="mb-2 block text-[11px] font-bold uppercase tracking-[0.08em] text-[#64748B]">WhatsApp connection</span><div className="flex h-10 items-center gap-2 rounded-lg border border-[#E2E8F0] bg-[#F8FAFC] px-3 text-xs font-medium text-[#1E293B]"><StatusDot color={whatsappStatus.data?.status === "connected" ? "#22C55E" : "#DC2626"} />{whatsappStatus.data?.status === "connected" ? "Connected via Baileys" : whatsappStatus.data?.status === "reconnect_required" ? "Reconnect required" : "Connection pending"}</div><span className="mt-1.5 block text-[10px] text-[#94A3B8]">Manage pairing from Connect WhatsApp.</span></div><div className="block"><span className="mb-2 block text-[11px] font-bold uppercase tracking-[0.08em] text-[#64748B]">Default language</span><div className="flex h-10 items-center rounded-lg border border-[#E2E8F0] bg-[#F8FAFC] px-3 text-xs font-medium text-[#64748B]">English + Singlish · mirrors client style</div></div></div></SettingsSection><SettingsSection title="Payment details" description="Bank details are inserted by code into fixed templates and never sent to the model."><label className="block"><span className="mb-2 block text-[11px] font-bold uppercase tracking-[0.08em] text-[#64748B]">Bank and payment instructions</span><textarea value={form.bankDetails} onChange={(event) => setField("bankDetails", event.target.value)} className="min-h-28 w-full rounded-lg border border-[#E2E8F0] bg-white px-3 py-2 text-xs leading-5 text-[#1E293B] outline-none focus:border-[#2563FF] focus:ring-2 focus:ring-[#DBEAFE]" placeholder="Bank name, account name, account number, branch, and payment instructions" /></label></SettingsSection><SettingsSection title="Usage guard" description="WEBASI warns at 70% and hard-stops at 90% of each configured cap."><div className="grid gap-4 sm:grid-cols-2">{input("WhatsApp monthly cap", "whatsappMonthlyCap", "Outbound messages per calendar month.")}{input("Gemini daily cap", "geminiDailyCap", "Structured model requests per day.")}</div><div className="mt-4 flex items-start gap-2 rounded-lg bg-[#EFF6FF] p-3 text-[11px] leading-5 text-[#1D4ED8]"><ShieldCheck className="mt-0.5 h-3.5 w-3.5 shrink-0" /><span>Caps are safety limits for the free tier. WEBASI stays silent when the hard-stop is reached until you override it.</span></div></SettingsSection><SettingsSection title="Automation safety" description="These switches control whether the assistant may send replies and whether drafts are sent to WhatsApp."><div className="grid gap-3 sm:grid-cols-2"><button onClick={() => setField("webasiEnabled", !form.webasiEnabled)} className={cn("flex items-center justify-between rounded-xl border p-4 text-left", form.webasiEnabled ? "border-[#BFDBFE] bg-[#EFF6FF]" : "border-[#E2E8F0] bg-white")}><span><span className="block text-xs font-bold text-[#1E293B]">Automation switch</span><span className="mt-1 block text-[11px] text-[#64748B]">{form.webasiEnabled ? "Replies are enabled" : "Incoming messages are logged only"}</span></span><span className={cn("rounded-full px-2 py-1 text-[10px] font-bold", form.webasiEnabled ? "bg-[#2563FF] text-white" : "bg-[#F1F5F9] text-[#64748B]")}>{form.webasiEnabled ? "ON" : "OFF"}</span></button><button onClick={() => setField("shadowMode", !form.shadowMode)} className={cn("flex items-center justify-between rounded-xl border p-4 text-left", form.shadowMode ? "border-[#FDE68A] bg-[#FFFBEB]" : "border-[#E2E8F0] bg-white")}><span><span className="block text-xs font-bold text-[#1E293B]">Shadow mode</span><span className="mt-1 block text-[11px] text-[#64748B]">{form.shadowMode ? "Draft replies only" : "Normal sending mode"}</span></span><span className={cn("rounded-full px-2 py-1 text-[10px] font-bold", form.shadowMode ? "bg-[#F59E0B] text-white" : "bg-[#F1F5F9] text-[#64748B]")}>{form.shadowMode ? "ON" : "OFF"}</span></button></div></SettingsSection><SettingsSection title="Keep-alive & system status" description="Render free services sleep after 15 minutes. This endpoint helps reduce cold starts."><div className="flex flex-col gap-3 rounded-xl border border-[#E2E8F0] bg-[#F8FAFC] p-4 sm:flex-row sm:items-center sm:justify-between"><div className="flex items-center gap-3"><div className="flex h-9 w-9 items-center justify-center rounded-lg bg-[#DCFCE7] text-[#15803D]"><ActivityIcon /></div><div><p className="text-xs font-semibold text-[#1E293B]">Keep-alive endpoint</p><p className="mt-1 text-[11px] text-[#64748B]">Available at /api/keepalive · Render free tier</p></div></div><span className="inline-flex w-fit items-center gap-1.5 rounded-full bg-[#DCFCE7] px-2.5 py-1 text-[10px] font-bold text-[#15803D]"><StatusDot />Operational</span></div></SettingsSection></div></div>;
}

function TrainingPage() {
  const projectsQuery = trpc.dashboard.projects.useQuery(undefined, { retry: false });
  const projects = projectsQuery.data ?? [];
  const defaultProjectKey = useMemo(() => projects.find((project) => project.status === "active")?.projectKey ?? projects[0]?.projectKey ?? "", [projects]);
  const [selectedProjectKey, setSelectedProjectKey] = useState("");
  const projectKey = selectedProjectKey || defaultProjectKey;
  const trainingQuery = trpc.projects.training.useQuery({ projectKey }, { enabled: Boolean(projectKey), retry: false });
  const [answers, setAnswers] = useState<Record<string, string>>({});
  const [summary, setSummary] = useState("");
  const [currentIndex, setCurrentIndex] = useState(0);
  useEffect(() => { if (trainingQuery.data) { setAnswers(trainingQuery.data.answers); setSummary(trainingQuery.data.summary); const next = trainingQuery.data.checklist.findIndex((item: string) => !trainingQuery.data?.answers[item]); setCurrentIndex(next >= 0 ? next : 0); } }, [trainingQuery.data]);
  const save = trpc.projects.saveTraining.useMutation({ onSuccess: () => { trainingQuery.refetch(); toast.success("Training answer saved"); }, onError: (error) => toast.error(error.message) });
  const approve = trpc.projects.approveTraining.useMutation({ onSuccess: () => { trainingQuery.refetch(); projectsQuery.refetch(); toast.success("Training approved", { description: "The project is ready to activate." }); }, onError: (error) => toast.error(error.message) });
  const checklist = trainingQuery.data?.checklist ?? [];
  const currentKey = checklist[currentIndex] ?? "";
  const completed = checklist.filter((item: string) => Boolean(answers[item]?.trim())).length;
  const progress = checklist.length ? Math.round((completed / checklist.length) * 100) : 0;
  const label = (key: string) => key.replace(/([A-Z])/g, " $1").replace(/^./, (value) => value.toUpperCase());
  const saveCurrent = () => { if (!projectKey || !currentKey || !answers[currentKey]?.trim()) { toast.error("Add an answer before saving"); return; } save.mutate({ projectKey, answers, summary }); };
  const approveSummary = () => { if (completed !== checklist.length) { toast.error("Complete every checklist item before approval"); return; } if (!summary.trim()) { toast.error("Review and enter a project summary before approval"); return; } if (window.confirm("Approve this training summary? The project can then be activated for client conversations.")) approve.mutate({ projectKey }); };
  if (!projectKey) return <div className="mx-auto max-w-[1100px] px-4 pb-12 pt-6 sm:px-6 lg:px-8 lg:pt-9"><PageHeader eyebrow="Workspace / Training" title="Project training" description="Create a project first, then complete its knowledge checklist." /><div className="webasi-card p-8 text-sm text-[#64748B]">No project is available yet. Create a draft from Projects to begin training.</div></div>;
  return <div className="mx-auto max-w-[1100px] px-4 pb-12 pt-6 sm:px-6 lg:px-8 lg:pt-9"><PageHeader eyebrow="Workspace / Training" title="Project training" description="Answer one question at a time. WEBASI stores the checklist and summary before approval." action={<span className="inline-flex items-center gap-1.5 rounded-full bg-[#EFF6FF] px-3 py-1.5 text-xs font-bold text-[#1D4ED8]"><Sparkles className="h-3.5 w-3.5" />{progress}% ready</span>} /><div className="mb-5 flex flex-wrap items-center gap-2 rounded-xl border border-[#E2E8F0] bg-white p-3"><span className="text-[11px] font-bold uppercase tracking-[0.08em] text-[#64748B]">Project</span><select value={projectKey} onChange={(event) => { setSelectedProjectKey(event.target.value); setAnswers({}); setSummary(""); setCurrentIndex(0); }} className="h-9 rounded-lg border border-[#E2E8F0] bg-white px-2.5 text-xs font-bold text-[#1D4ED8] outline-none focus:border-[#2563FF]">{projects.map((project) => <option key={project.projectKey} value={project.projectKey}>{project.name} · v{project.version}</option>)}</select><span className="text-[11px] text-[#94A3B8]">Complete and approve this project before activation.</span></div><div className="grid gap-5 lg:grid-cols-[minmax(0,1fr)_310px]"><section className="webasi-card flex min-h-[560px] flex-col overflow-hidden"><div className="flex items-center justify-between border-b border-[#E2E8F0] p-5"><div><p className="text-sm font-bold text-[#1E293B]">Training interview</p><p className="mt-1 text-xs text-[#94A3B8]">One grounded answer at a time</p></div><span className="text-xs font-semibold text-[#64748B]">{completed} / {checklist.length} complete</span></div><div className="flex-1 space-y-5 bg-[#F8FAFC] p-5 sm:p-8"><div className="flex justify-start"><div className="max-w-[82%] rounded-2xl rounded-bl-md border border-[#E2E8F0] bg-white px-4 py-3 text-sm leading-6 text-[#1E293B] shadow-sm">What should WEBASI know about <strong>{label(currentKey).toLowerCase()}</strong>? Give a precise answer that can be safely used with clients.<span className="mt-1 block text-[10px] text-[#94A3B8]">WEBASI · checklist item {currentIndex + 1}</span></div></div><div className="flex justify-end"><div className="max-w-[82%] rounded-2xl rounded-br-md bg-[#2563FF] px-4 py-3 text-sm leading-6 text-white shadow-sm">{answers[currentKey] || "I’m ready to answer this item."}</div></div></div><div className="border-t border-[#E2E8F0] bg-white p-4"><div className="flex items-end gap-2 rounded-xl border border-[#E2E8F0] bg-[#F8FAFC] p-2"><textarea value={answers[currentKey] ?? ""} onChange={(event) => setAnswers((current) => ({ ...current, [currentKey]: event.target.value }))} className="min-h-12 flex-1 resize-none bg-transparent px-2 py-1 text-xs leading-5 outline-none" placeholder="Type your answer…" /><button onClick={() => { saveCurrent(); if (answers[currentKey]?.trim() && currentIndex < checklist.length - 1) setCurrentIndex((index) => index + 1); }} disabled={save.isPending} className="webasi-button-primary min-h-9 px-3"><Send className="h-3.5 w-3.5" />{save.isPending ? "Saving…" : "Save & next"}</button></div></div></section><section className="space-y-5"><div className="webasi-card p-5"><div className="mb-4 flex items-center justify-between"><div><p className="webasi-label mb-2">Checklist</p><h2 className="text-base font-bold text-[#0F172A]">Knowledge readiness</h2></div><span className="text-xs font-bold text-[#2563FF]">{progress}%</span></div><div className="mb-5 h-2 overflow-hidden rounded-full bg-[#F1F5F9]"><div className="h-full rounded-full bg-[#2563FF] transition-all" style={{ width: `${progress}%` }} /></div><div className="space-y-3">{checklist.map((item: string, index: number) => <button key={item} onClick={() => setCurrentIndex(index)} className="flex w-full items-center gap-2.5 text-left text-xs"><span className={cn("flex h-5 w-5 items-center justify-center rounded-full", answers[item]?.trim() ? "bg-[#DCFCE7] text-[#15803D]" : index === currentIndex ? "bg-[#DBEAFE] text-[#1D4ED8]" : "bg-[#F1F5F9] text-[#94A3B8]")}>{answers[item]?.trim() ? <Check className="h-3 w-3" /> : <span className="h-1.5 w-1.5 rounded-full bg-current" />}</span><span className={answers[item]?.trim() ? "font-medium text-[#1E293B]" : "text-[#64748B]"}>{label(item)}</span></button>)}</div></div><div className="webasi-card border-[#C7D8FF] bg-[#EFF6FF] p-5"><p className="text-xs font-bold text-[#1D4ED8]">Summary approval</p><p className="mt-2 text-xs leading-5 text-[#1E40AF]">Review the summary before this project can become eligible for activation.</p><textarea value={summary} onChange={(event) => setSummary(event.target.value)} className="mt-4 min-h-24 w-full rounded-lg border border-[#BFDBFE] bg-white p-3 text-xs leading-5 text-[#1E293B] outline-none focus:border-[#2563FF]" placeholder="Write the approved project summary…" /><div className="mt-3 flex gap-2"><button onClick={() => save.mutate({ projectKey, answers, summary })} disabled={save.isPending} className="webasi-button-secondary min-h-9 px-3">Save draft</button><button onClick={approveSummary} disabled={approve.isPending} className="webasi-button-primary min-h-9 px-3">{approve.isPending ? "Approving…" : "Approve summary"}</button></div></div></section></div></div>;
}

function MetricCard({ label, value, detail, icon: Icon, tone = "blue" }: { label: string; value: string; detail: string; icon: typeof Sparkles; tone?: "blue" | "violet" | "green" | "amber" }) { const colors = { blue: "bg-[#EFF6FF] text-[#2563FF]", violet: "bg-[#F5F3FF] text-[#7C3AED]", green: "bg-[#F0FDF4] text-[#16A34A]", amber: "bg-[#FFF7ED] text-[#F59E0B]" }; return <div className="webasi-card p-4"><div className="flex items-start justify-between"><div><p className="webasi-label">{label}</p><p className="mt-2 text-[26px] font-bold tracking-[-0.05em] text-[#0F172A]">{value}</p><p className="mt-1 text-[11px] text-[#94A3B8]">{detail}</p></div><div className={cn("flex h-9 w-9 items-center justify-center rounded-lg", colors[tone])}><Icon className="h-4 w-4" /></div></div></div>; }
function SettingsSection({ title, description, children }: { title: string; description: string; children: ReactNode }) { return <section className="webasi-card p-5 sm:p-6"><div className="mb-5"><h2 className="text-base font-bold text-[#0F172A]">{title}</h2><p className="mt-1.5 text-xs leading-5 text-[#64748B]">{description}</p></div>{children}</section>; }
function Field({ label, value, helper }: { label: string; value: string; helper?: string }) { return <label className="block"><span className="mb-2 block text-[11px] font-bold uppercase tracking-[0.08em] text-[#64748B]">{label}</span><input defaultValue={value} className="h-10 w-full rounded-lg border border-[#E2E8F0] bg-white px-3 text-xs font-medium text-[#1E293B] outline-none transition focus:border-[#2563FF] focus:ring-2 focus:ring-[#DBEAFE]" />{helper && <span className="mt-1.5 block text-[10px] text-[#94A3B8]">{helper}</span>}</label>; }
function ActivityIcon() { return <span className="relative flex h-4 w-4 items-center justify-center"><span className="absolute h-2.5 w-2.5 rounded-full border-2 border-current" /><span className="absolute h-1 w-1 rounded-full bg-current" /></span>; }

export default function Home() {
  const [location] = useLocation();
  const page = useMemo(() => location || "/", [location]);
  if (page === "/projects") return <ProjectsPage />;
  if (page === "/training") return <TrainingPage />;
  if (page === "/conversations") return <ConversationsPage />;
  if (page === "/orders") return <OrdersPage />;
  if (page === "/insights") return <InsightsPage />;
  if (page === "/settings") return <SettingsPage />;
  if (page === "/test-chat") return <TestChatPage />;
  if (page === "/events") return <EventsPage />;
  if (page === "/connect-whatsapp") return <ConnectWhatsApp />;
  return <HomePage />;
}

function TestChatPage() { const projectsQuery = trpc.dashboard.projects.useQuery(undefined, { retry: false }); const projects = projectsQuery.data ?? []; const [projectKey, setProjectKey] = useState(""); const [messages, setMessages] = useState<Array<{ role: "client" | "assistant"; text: string }>>([]); const [draft, setDraft] = useState(""); const turn = trpc.testChat.turn.useMutation({ onSuccess: (reply) => { setMessages((items) => [...items, { role: "assistant", text: reply.reply }]); }, onError: (error) => toast.error(error.message) }); useEffect(() => { if (!projectKey && projects[0]) setProjectKey(projects[0].projectKey); }, [projectKey, projects]); const selected = projects.find((project) => project.projectKey === projectKey); const send = () => { const incomingText = draft.trim(); if (!incomingText || !projectKey || turn.isPending) return; const next = [...messages, { role: "client" as const, text: incomingText }]; setMessages(next); setDraft(""); turn.mutate({ projectKey, incomingText, recentMessages: messages, state: "collecting" }); }; return <div className="mx-auto max-w-[1100px] px-4 pb-12 pt-6 sm:px-6 lg:px-8 lg:pt-9"><PageHeader eyebrow="Workspace / Test Chat" title="Test Chat" description="Play the role of a client against a project snapshot. This sandbox never sends WhatsApp messages, writes conversations, or uses production caps." action={<span className="inline-flex items-center gap-1.5 rounded-full bg-[#F0FDF4] px-3 py-1.5 text-xs font-bold text-[#15803D]"><StatusDot />Sandbox mode</span>} /><div className="mb-5 flex flex-wrap items-center gap-2 rounded-xl border border-[#E2E8F0] bg-white p-3"><span className="text-[11px] font-bold uppercase tracking-[0.08em] text-[#64748B]">Project snapshot</span><select value={projectKey} onChange={(event) => { setProjectKey(event.target.value); setMessages([]); }} className="h-9 rounded-lg border border-[#E2E8F0] bg-white px-2.5 text-xs font-bold text-[#1D4ED8]">{projects.map((project) => <option key={project.projectKey} value={project.projectKey}>{project.name} · v{project.version}</option>)}</select><span className="text-[11px] text-[#94A3B8]">No WhatsApp delivery · no usage count</span></div><section className="webasi-card mx-auto flex min-h-[560px] max-w-3xl flex-col overflow-hidden"><div className="flex items-center gap-3 border-b border-[#E2E8F0] p-5"><div className="flex h-9 w-9 items-center justify-center rounded-xl bg-[#2563FF] text-white"><Bot className="h-4 w-4" /></div><div><p className="text-sm font-bold text-[#1E293B]">WEBASI test assistant</p><p className="mt-0.5 text-[11px] text-[#64748B]">Using {selected?.name ?? "selected project"} · grounded sandbox</p></div></div><div className="flex-1 space-y-4 overflow-auto bg-[#F8FAFC] p-5 sm:p-8">{messages.length === 0 ? <div className="flex h-full min-h-[360px] items-center justify-center text-center text-xs leading-5 text-[#94A3B8]">Start with a client message to test the selected project.<br />Try a greeting, a price question, or a Singlish message.</div> : messages.map((message, index) => <div key={`${message.role}-${index}-${message.text}`} className={cn("flex", message.role === "client" ? "justify-end" : "justify-start")}><div className={cn("max-w-[78%] rounded-2xl px-4 py-3 text-sm leading-6 shadow-sm", message.role === "client" ? "rounded-br-md bg-[#2563FF] text-white" : "rounded-bl-md border border-[#E2E8F0] bg-white text-[#1E293B]")}>{message.text}<span className={cn("mt-1 block text-[10px]", message.role === "client" ? "text-blue-100" : "text-[#94A3B8]")}>{message.role === "client" ? "You · sandbox" : "WEBASI · sandbox"}</span></div></div>)}</div><div className="border-t border-[#E2E8F0] bg-white p-4"><div className="flex gap-2"><input value={draft} onChange={(event) => setDraft(event.target.value)} onKeyDown={(event) => event.key === "Enter" && send()} disabled={turn.isPending || !projectKey} className="h-10 flex-1 rounded-lg border border-[#E2E8F0] px-3 text-xs outline-none focus:border-[#2563FF]" placeholder={turn.isPending ? "WEBASI is thinking…" : "Type a client message…"} /><button onClick={send} disabled={turn.isPending || !projectKey} className="webasi-button-primary min-h-10 px-3"><Send className="h-3.5 w-3.5" />{turn.isPending ? "Thinking…" : "Send"}</button></div></div></section></div>; }
function EventsPage() { const [filter, setFilter] = useState<"all" | "warning" | "error">("all"); const eventsQuery = trpc.dashboard.events.useQuery(undefined, { refetchInterval: 10000, retry: false }); const events = eventsQuery.data ?? []; const filtered = filter === "all" ? events : events.filter((event) => event.severity === filter); const tone = (severity: string) => severity === "error" ? "bg-[#FEF2F2] text-[#B91C1C]" : severity === "warning" ? "bg-[#FFF7ED] text-[#D97706]" : "bg-[#EFF6FF] text-[#2563FF]"; return <div className="mx-auto max-w-[1100px] px-4 pb-12 pt-6 sm:px-6 lg:px-8 lg:pt-9"><PageHeader eyebrow="Workspace / Event log" title="Event log" description="A live trace of safety-critical actions, WhatsApp transport events, and escalations." action={<button onClick={() => eventsQuery.refetch()} disabled={eventsQuery.isFetching} className="webasi-button-secondary"><RefreshCw className={cn("h-4 w-4", eventsQuery.isFetching && "animate-spin")} />Refresh</button>} /><section className="webasi-card overflow-hidden"><div className="flex flex-col gap-3 border-b border-[#E2E8F0] p-5 sm:flex-row sm:items-center sm:justify-between"><div><h2 className="text-base font-bold text-[#0F172A]">System activity</h2><p className="mt-1 text-xs text-[#94A3B8]">Showing the latest 50 persisted events</p></div><div className="flex gap-1.5"><button onClick={() => setFilter("all")} className={cn("rounded-full px-2.5 py-1 text-[10px] font-bold", filter === "all" ? "bg-[#EFF6FF] text-[#1D4ED8]" : "text-[#64748B] hover:bg-[#F8FAFC]")}>All {events.length}</button><button onClick={() => setFilter("warning")} className={cn("rounded-full px-2.5 py-1 text-[10px] font-bold", filter === "warning" ? "bg-[#FFF7ED] text-[#C2410C]" : "text-[#64748B] hover:bg-[#F8FAFC]")}>Warnings</button><button onClick={() => setFilter("error")} className={cn("rounded-full px-2.5 py-1 text-[10px] font-bold", filter === "error" ? "bg-[#FEF2F2] text-[#B91C1C]" : "text-[#64748B] hover:bg-[#F8FAFC]")}>Errors</button></div></div><div className="divide-y divide-[#F1F5F9]">{eventsQuery.isLoading ? <div className="p-6 text-xs text-[#94A3B8]">Loading persisted events…</div> : filtered.length === 0 ? <div className="p-6 text-xs text-[#94A3B8]">No events match this filter.</div> : filtered.map((event) => <div key={event.id} className="flex gap-3 p-5"><div className={cn("mt-0.5 flex h-8 w-8 shrink-0 items-center justify-center rounded-lg", tone(event.severity))}><FileClock className="h-4 w-4" /></div><div className="min-w-0"><div className="flex flex-wrap items-center gap-2"><p className="text-xs font-semibold text-[#1E293B]">{event.title}</p><span className={cn("rounded-full px-2 py-0.5 text-[10px] font-bold uppercase", tone(event.severity))}>{event.severity}</span></div><p className="mt-1 text-xs text-[#64748B]">{event.detail}</p><p className="mt-2 text-[10px] font-medium text-[#94A3B8]">{new Date(event.createdAt).toLocaleString([], { dateStyle: "medium", timeStyle: "short" })}</p></div></div>)}</div></section></div>; }
